 async function connectDomain(){const domain=(document.getElementById('customDomainInput') as HTMLInputElement)?.value||'',r=await fetch('/api/domains',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({businessId:currentBusiness.id,domain})}),j=await r.json();if(!r.ok)return notify(j.error);await load();notify(j.domain?.verified?'Domain aktif.':'Domain eklendi; DNS bağlantı bilgileri.')}
